#[test]
fn golden_vectors_have_the_documented_shapes() {
    assert_eq!(CH4_CTX_IN.len(), 70);
    assert_eq!(CH5_CTX_OUT.len(), CH4_CTX_IN.len());
    assert_eq!(CH4_FRAMES_IN.len(), 24);
    assert_eq!(CH5_FRAMES_OUT.len(), CH4_FRAMES_IN.len());
    assert!(CH4_FRAMES_IN != CH4_FRAMES_OUT);
}
